import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();

        if (n >= 4 && m >= 4) {
            System.out.println(n * m - ((n * m) % 2));
        } else {
            int smaller = Math.min(n, m);
            int larger = Math.max(n, m);
            if (smaller == 1) {
                int r = larger;
                if (r % 6 == 5) {
                    System.out.println((r / 6) * 6 + 4);
                } else if (r % 6 == 4) {
                    System.out.println((r / 6) * 6 + 2);
                } else {
                    System.out.println((r / 6) * 6);
                }
            } else if (smaller == 2 && larger == 7) {
                System.out.println(12);
            } else if ((smaller == 2 && larger >= 4) || (smaller == 3 && larger >= 4)) {
                System.out.println(n * m - ((n * m) % 2));
            } else {
                int[][] d = {
                    {0, 0, 0, 2, 4},
                    {0, 0, 4, 8, 10},
                    {0, 0, 8, 12, 14},
                    {0, 0, 0, 16, 20},
                    {0, 0, 0, 0, 24}
                };
                System.out.println(d[smaller - 1][larger - 1]);
            }
        }
        sc.close();
    }
}

